function makeId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function clean(value, fallback = "", limit = 1200) {
  if (typeof value !== "string") return fallback;
  const result = value.trim();
  return result ? result.slice(0, limit) : fallback;
}
function now() {
  return new Date().toISOString();
}
function emptyData() {
  return { queues: [], assignments: [], reviews: [], notes: [], owners: [] };
}
function readData() {
  if (typeof window === "undefined") return emptyData();
  try {
    return { ...emptyData(), ...JSON.parse(window.localStorage.getItem(STORAGE_KEY) || "{}") };
  } catch {
    return emptyData();
  }
}
function tone(value) {
  if (["resolved", "done", "low"].includes(value)) return "emerald";
  if (["critical", "high", "blocked"].includes(value)) return "rose";
  if (["in-progress", "medium", "assigned"].includes(value)) return "amber";
  return "slate";
}
function Badge({ children, value }) {
  const colors = { slate: "border-slate-200 bg-slate-50 text-slate-700", emerald: "border-emerald-200 bg-emerald-50 text-emerald-800", amber: "border-amber-200 bg-amber-50 text-amber-800", rose: "border-rose-200 bg-rose-50 text-rose-800" };
  return <span className={`inline-flex rounded-full border px-2.5 py-1 text-[11px] font-semibold ${colors[tone(value)] || colors.slate}`}>{children}</span>;
}
function Button({ children, icon: Icon, onClick, variant = "secondary", type = "button" }) {
  const variants = { secondary: "border-slate-200 bg-white text-slate-700 hover:border-slate-300", primary: "border-blue-600 bg-blue-600 text-white hover:bg-blue-700", danger: "border-rose-200 bg-white text-rose-700 hover:bg-rose-50" };
  return <button type={type} onClick={onClick} className={`inline-flex h-9 items-center justify-center gap-2 rounded-lg border px-3 text-xs font-semibold ${variants[variant]}`}>{Icon && <Icon size={14} />}{children}</button>;
}
function Field({ label, value, onChange, placeholder, options, required = false }) {
  const common = { value: value || "", onChange: (event) => onChange(event.target.value), required, className: "mt-1.5 h-10 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm outline-none focus:border-blue-500" };
  return <label className="block text-xs font-semibold text-slate-700">{label}{options ? <select {...common}><option value="">Select...</option>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select> : <input {...common} placeholder={placeholder} />}</label>;
}
function Area({ label, value, onChange, placeholder }) {
  return <label className="block text-xs font-semibold text-slate-700">{label}<textarea value={value || ""} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} rows={4} className="mt-1.5 w-full resize-y rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-blue-500" /></label>;
}
function Empty({ title, description, action }) {
  return <div className="p-8 text-center"><p className="text-sm font-semibold text-slate-800">{title}</p><p className="mx-auto mt-1 max-w-md text-xs text-slate-500">{description}</p>{action && <div className="mt-4">{action}</div>}</div>;
}
function Section({ title, description, action, children }) {
  return <section className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-start justify-between gap-3 border-b border-slate-100 p-5"><div><h3 className="text-sm font-semibold text-slate-950">{title}</h3><p className="mt-1 text-xs text-slate-500">{description}</p></div>{action}</div>{children}</section>;
}
function Modal({ title, onClose, children }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/30 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="flex items-center justify-between border-b p-5"><h2 className="font-semibold">{title}</h2><button type="button" onClick={onClose}><X size={17} /></button></div><div className="p-5">{children}</div></div></div>;
}
function Stat({ icon: Icon, label, value, detail }) {
  return <article className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-3xl font-semibold">{value}</p></div><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-blue-100 text-blue-700"><Icon size={17} /></span></div><p className="mt-2 text-[11px] text-slate-500">{detail}</p></article>;
}

export default function AssignmentGovernancePage() {
  const [data, setData] = useState(emptyData);
  const [selectedId, setSelectedId] = useState("");
  const [tab, setTab] = useState("overview");
  const [query, setQuery] = useState("");
  const [ascending, setAscending] = useState(false);
  const [modal, setModal] = useState("");
  const [notice, setNotice] = useState("");
  const [queueForm, setQueueForm] = useState({ title: "", queue: "New reports", owner: "", target: "", summary: "" });
  const [assignmentForm, setAssignmentForm] = useState({ title: "", state: "unassigned", priority: "medium", owner: "", due: "", detail: "" });
  const [reviewForm, setReviewForm] = useState({ title: "", type: "SLA review", state: "planned", owner: "", finding: "", next: "" });
  const [noteForm, setNoteForm] = useState({ title: "", kind: "Assignment note", author: "", detail: "" });
  const [ownerForm, setOwnerForm] = useState({ name: "", role: "", area: "", capacity: "", backup: "" });

  useEffect(() => setData(readData()), []);
  useEffect(() => { if (typeof window !== "undefined") window.localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }, [data]);
  useEffect(() => { if (!notice) return undefined; const timer = window.setTimeout(() => setNotice(""), 2500); return () => window.clearTimeout(timer); }, [notice]);

  const queue = data.queues.find((item) => item.id === selectedId);
  const assignments = data.assignments.filter((item) => !selectedId || item.queueId === selectedId);
  const reviews = data.reviews.filter((item) => !selectedId || item.queueId === selectedId);
  const notes = data.notes.filter((item) => !selectedId || item.queueId === selectedId);
  const owners = data.owners.filter((item) => !selectedId || item.queueId === selectedId);
  const active = assignments.filter((item) => !["resolved", "deferred"].includes(item.state));
  const blocked = assignments.filter((item) => item.state === "blocked");
  const done = assignments.filter((item) => item.state === "resolved").length;
  const score = assignments.length ? Math.round((done / assignments.length) * 100) : 0;
  const filtered = useMemo(() => assignments.filter((item) => `${item.title} ${item.owner} ${item.priority} ${item.detail}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => { const result = a.title.localeCompare(b.title); return ascending ? result : result * -1; }), [ascending, assignments, query]);

  function update(key, items) { setData((current) => ({ ...current, [key]: items })); }
  function addQueue(event) { event.preventDefault(); const item = { ...queueForm, id: makeId("queue"), title: clean(queueForm.title), owner: clean(queueForm.owner), target: clean(queueForm.target), summary: clean(queueForm.summary), createdAt: now() }; update("queues", [item, ...data.queues]); setSelectedId(item.id); setQueueForm({ title: "", queue: "New reports", owner: "", target: "", summary: "" }); setModal(""); setNotice("Assignment queue created"); }
  function addAssignment(event) { event.preventDefault(); const item = { ...assignmentForm, id: makeId("assignment"), queueId: selectedId, title: clean(assignmentForm.title), owner: clean(assignmentForm.owner), due: clean(assignmentForm.due), detail: clean(assignmentForm.detail), createdAt: now() }; update("assignments", [item, ...data.assignments]); setAssignmentForm({ title: "", state: "unassigned", priority: "medium", owner: "", due: "", detail: "" }); setModal(""); setNotice("Assignment item added"); }
  function addReview(event) { event.preventDefault(); const item = { ...reviewForm, id: makeId("review"), queueId: selectedId, title: clean(reviewForm.title), owner: clean(reviewForm.owner), finding: clean(reviewForm.finding), next: clean(reviewForm.next), createdAt: now() }; update("reviews", [item, ...data.reviews]); setReviewForm({ title: "", type: "SLA review", state: "planned", owner: "", finding: "", next: "" }); setModal(""); setNotice("Queue review added"); }
  function addNote(event) { event.preventDefault(); const item = { ...noteForm, id: makeId("note"), queueId: selectedId, title: clean(noteForm.title), author: clean(noteForm.author), detail: clean(noteForm.detail), createdAt: now() }; update("notes", [item, ...data.notes]); setNoteForm({ title: "", kind: "Assignment note", author: "", detail: "" }); setModal(""); setNotice("Assignment note added"); }
  function addOwner(event) { event.preventDefault(); const item = { ...ownerForm, id: makeId("owner"), queueId: selectedId, name: clean(ownerForm.name), role: clean(ownerForm.role), area: clean(ownerForm.area), capacity: clean(ownerForm.capacity), backup: clean(ownerForm.backup), createdAt: now() }; update("owners", [item, ...data.owners]); setOwnerForm({ name: "", role: "", area: "", capacity: "", backup: "" }); setModal(""); setNotice("Queue owner added"); }
  function change(key, itemId, field, value) { update(key, data[key].map((item) => item.id === itemId ? { ...item, [field]: value, updatedAt: now() } : item)); }
  function remove(key, itemId) { update(key, data[key].filter((item) => item.id !== itemId)); setNotice("Record removed"); }
  function applyLibrary() { if (!selectedId) { setNotice("Select a queue first"); return; } const items = ASSIGNMENT_LIBRARY.slice(0, 30).map((title, index) => ({ id: makeId(`assignment-${index}`), queueId: selectedId, title, state: "unassigned", priority: index < 3 ? "high" : "medium", owner: "", due: "", detail: "", createdAt: now() })); update("assignments", [...items, ...data.assignments]); setNotice("Assignment review library applied"); }
  function copySummary() { navigator.clipboard?.writeText([`Queue: ${queue?.title || "All queues"}`, `Completion: ${score}%`, `Active: ${active.length}`, `Blocked: ${blocked.length}`, `Reviews: ${reviews.length}`, `Notes: ${notes.length}`, `Owners: ${owners.length}`, queue?.summary || "No summary recorded."].join("\n")); setNotice("Assignment summary copied"); }
  function exportRows() { const rows = [["Type", "Title", "State", "Priority", "Owner", "Detail"], ...assignments.map((item) => ["Assignment", item.title, item.state, item.priority, item.owner, item.detail]), ...reviews.map((item) => ["Review", item.title, item.state, "", item.owner, item.finding]), ...notes.map((item) => ["Note", item.title, item.kind, "", item.author, item.detail])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell || "").replaceAll('"', '""')}"`).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "assignment-governance.csv"; anchor.click(); URL.revokeObjectURL(url); setNotice("Assignment export downloaded"); }

  const tabs = [["overview", "Overview"], ["assignments", `Assignments (${assignments.length})`], ["reviews", `Reviews (${reviews.length})`], ["notes", `Notes (${notes.length})`], ["owners", `Owners (${owners.length})`]];
  return <main className="min-h-screen bg-slate-50 px-4 py-8 text-slate-900 sm:px-8"><div className="mx-auto max-w-7xl space-y-5">
    <div className="rounded-3xl border border-blue-200 bg-gradient-to-br from-blue-50 via-white to-slate-50 p-5 shadow-sm sm:p-7"><div className="flex flex-col gap-5 lg:flex-row lg:justify-between"><div className="max-w-3xl"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.16em] text-blue-700"><ShieldCheck size={16} /> Admin assignment governance</div><h1 className="mt-3 text-2xl font-semibold tracking-tight sm:text-3xl">Balance assignment queues with explicit ownership and audit context.</h1><p className="mt-3 text-sm leading-6 text-slate-600">A browser-local administration workspace for queue health, workload decisions, SLA reviews, and handoffs. It does not mutate backend assignment data.</p></div><div className="flex flex-wrap gap-2"><Button icon={Plus} variant="primary" onClick={() => setModal("queue")}>New queue</Button><Button icon={Copy} onClick={copySummary}>Copy summary</Button><Button icon={Download} onClick={exportRows}>Export</Button></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Stat icon={Gauge} label="Completion" value={`${score}%`} detail={`${done} resolved items`} /><Stat icon={AlertTriangle} label="Blocked" value={blocked.length} detail={`${active.length} active assignments`} /><Stat icon={ClipboardCheck} label="Reviews" value={reviews.length} detail="Queue governance reviews" /><Stat icon={Users} label="Owners" value={owners.length} detail="Primary and backup owners" /></div></div>
    {notice && <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs font-semibold text-emerald-800">{notice}</div>}
    <div className="flex flex-wrap gap-2 border-b border-slate-200 pb-1">{tabs.map(([value, label]) => <button key={value} type="button" onClick={() => setTab(value)} className={`rounded-t-lg px-3 py-2 text-xs font-semibold ${tab === value ? "border-b-2 border-blue-600 text-blue-700" : "text-slate-500"}`}>{label}</button>)}</div>
    <Section title="Queue context" description="Select the assignment queue you want to review." action={<Button icon={RefreshCw} onClick={() => { setData(readData()); setNotice("Assignment workspace refreshed"); }}>Refresh</Button>}><div className="grid gap-4 p-5 lg:grid-cols-[minmax(0,1fr)_auto]"><label className="text-xs font-semibold text-slate-700">Selected queue<select value={selectedId} onChange={(event) => setSelectedId(event.target.value)} className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm"><option value="">All queues</option>{data.queues.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><div className="flex items-end gap-2"><Button icon={LayoutList} onClick={applyLibrary}>Apply review library</Button><Button icon={Plus} onClick={() => setModal("queue")}>Add queue</Button></div></div><div className="grid gap-3 border-t border-slate-100 p-5 md:grid-cols-2 xl:grid-cols-3">{data.queues.map((item) => <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} className={`rounded-xl border p-4 text-left ${selectedId === item.id ? "border-blue-300 bg-blue-50" : "border-slate-200"}`}><div className="flex items-start justify-between gap-3"><p className="text-sm font-semibold">{item.title}</p><Badge value={item.queue}>{item.queue}</Badge></div><p className="mt-2 line-clamp-2 text-xs text-slate-500">{item.summary || "No queue summary recorded."}</p><p className="mt-3 text-[11px] text-slate-400">{item.target || "No target"} · {item.owner || "Unassigned"}</p></button>)}{!data.queues.length && <div className="md:col-span-2 xl:col-span-3"><Empty title="No assignment queue" description="Create a queue review for triage, verification, release, or escalation work." action={<Button icon={Plus} variant="primary" onClick={() => setModal("queue")}>Create queue</Button>} /></div>}</div></Section>
    {tab === "overview" && <div className="grid gap-5 xl:grid-cols-2"><Section title="Queue posture" description="Understand where assignment attention is needed."><div className="space-y-4 p-5"><div className="rounded-xl border border-blue-100 bg-blue-50 p-4"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-blue-900">Assignment completion</p><p className="text-lg font-semibold text-blue-900">{score}%</p></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-white"><div className="h-full rounded-full bg-blue-600" style={{ width: `${score}%` }} /></div><p className="mt-3 text-xs text-blue-800">{blocked.length ? `${blocked.length} blocked assignment${blocked.length === 1 ? "" : "s"} need escalation.` : "No blocked assignments recorded."}</p></div><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Active</p><p className="mt-1 text-xl font-semibold">{active.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Reviews</p><p className="mt-1 text-xl font-semibold">{reviews.length}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-500">Notes</p><p className="mt-1 text-xl font-semibold">{notes.length}</p></div></div><p className="text-[11px] text-slate-500">Assignment library: {ASSIGNMENT_LIBRARY.length} reusable prompts for routing, SLA review, evidence, and handoff. Audit library: {AUDIT_PROMPTS.length} additional checks.</p></div></Section><Section title="Queue narrative" description="Keep the reason for the workload decision visible."><div className="space-y-4 p-5"><Area label="Summary" value={queue?.summary || ""} onChange={(value) => queue && change("queues", queue.id, "summary", value)} placeholder="What does this queue contain and why is it being reviewed?" /><Area label="Decision note" value={queue?.decision || ""} onChange={(value) => queue && change("queues", queue.id, "decision", value)} placeholder="What should change after this review?" /></div></Section><Section title="Assignment principles" description="Use consistent rules when the queue is under pressure."><div className="grid gap-3 p-5 sm:grid-cols-2">{[["Prioritize impact", "Customer harm and release risk should shape ordering.", AlertTriangle], ["Name an owner", "Every active item needs a clear next person.", Users], ["Make handoffs explicit", "Record what the next owner receives.", ClipboardCheck], ["Audit the decision", "Keep enough context to explain routing later.", ShieldCheck]].map(([title, detail, Icon]) => <div key={title} className="rounded-xl border border-slate-200 p-4"><Icon size={17} className="text-blue-600" /><p className="mt-3 text-sm font-semibold">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">{detail}</p></div>)}</div></Section><Section title="Queue review prompts" description="Load a prompt into a new assignment item."><div className="grid gap-2 p-5 sm:grid-cols-2">{ASSIGNMENT_LIBRARY.slice(0, 12).map((prompt) => <button key={prompt} type="button" onClick={() => { setTab("assignments"); setAssignmentForm((current) => ({ ...current, title: prompt })); setNotice("Prompt loaded into assignment form"); }} className="rounded-lg border border-slate-200 px-3 py-2 text-left text-[11px] text-slate-600 hover:border-blue-300 hover:text-blue-700">{prompt}</button>)}</div><p className="mt-4 px-5 pb-5 text-[11px] text-slate-400">Use audit prompts to add evidence and rationale checks to the assignment queue.</p></Section></div>}
    {tab === "assignments" && <Section title="Assignment items" description="Track work, ownership, priority, and handoff state." action={<Button icon={Plus} variant="primary" onClick={() => setModal("assignment")}>Add assignment</Button>}><div className="flex gap-3 border-b border-slate-100 p-5"><div className="relative min-w-0 flex-1"><Search size={15} className="absolute left-3 top-3 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search assignments, owners, priorities..." className="h-10 w-full rounded-lg border border-slate-200 pl-9 pr-3 text-sm" /></div><Button icon={ascending ? ArrowUpAZ : ArrowDownAZ} onClick={() => setAscending((value) => !value)}>Sort</Button></div>{!filtered.length ? <Empty title="No assignment items" description="Apply the review library or add a targeted assignment." action={<Button icon={LayoutList} onClick={applyLibrary}>Apply library</Button>} /> : <div className="divide-y">{filtered.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.state}>{item.state}</Badge><Badge value={item.priority}>{item.priority}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No assignment detail recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Due: {item.due || "Not set"}</p></div><div className="flex gap-2"><select value={item.state} onChange={(event) => change("assignments", item.id, "state", event.target.value)} className="h-8 rounded-lg border border-slate-200 px-2 text-[11px]">{STATES.map((state) => <option key={state} value={state}>{state}</option>)}</select><Button variant="danger" icon={Trash2} onClick={() => remove("assignments", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {tab === "reviews" && <Section title="Queue governance reviews" description="Capture SLA, ownership, severity, and escalation decisions." action={<Button icon={Plus} variant="primary" onClick={() => setModal("review")}>Add review</Button>}>{!reviews.length ? <Empty title="No queue reviews" description="Record an SLA review, ownership check, or escalation decision." action={<Button icon={Plus} onClick={() => setModal("review")}>Add review</Button>} /> : <div className="divide-y">{reviews.map((item) => <div key={item.id} className="flex flex-col gap-3 p-5 lg:flex-row lg:justify-between"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.state}>{item.state}</Badge><Badge value={item.type}>{item.type}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.finding || "No finding recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Owner: {item.owner || "Unassigned"} · Next: {item.next || "Not set"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("reviews", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "notes" && <Section title="Assignment audit notes" description="Keep routing rationale and handoff context discoverable." action={<Button icon={Plus} variant="primary" onClick={() => setModal("note")}>Add note</Button>}>{!notes.length ? <Empty title="No assignment notes" description="Record why an item was routed, deferred, escalated, or resolved." action={<Button icon={Plus} onClick={() => setModal("note")}>Add note</Button>} /> : <div className="divide-y">{notes.map((item) => <div key={item.id} className="flex justify-between gap-3 p-5"><div><div className="flex flex-wrap gap-2"><h4 className="text-sm font-semibold">{item.title}</h4><Badge value={item.kind}>{item.kind}</Badge></div><p className="mt-2 text-xs text-slate-600">{item.detail || "No note detail recorded."}</p><p className="mt-2 text-[11px] text-slate-500">Author: {item.author || "Not set"}</p></div><Button variant="danger" icon={Trash2} onClick={() => remove("notes", item.id)}>Remove</Button></div>)}</div>}</Section>}
    {tab === "owners" && <Section title="Queue ownership" description="Map primary, backup, and domain ownership for assignment work." action={<Button icon={Plus} variant="primary" onClick={() => setModal("owner")}>Add owner</Button>}>{!owners.length ? <Empty title="No queue owners" description="Add primary and backup ownership for the review." action={<Button icon={Plus} onClick={() => setModal("owner")}>Add owner</Button>} /> : <div className="grid gap-3 p-5 md:grid-cols-2">{owners.map((item) => <div key={item.id} className="rounded-xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><div><p className="text-sm font-semibold">{item.name}</p><p className="mt-1 text-xs text-slate-500">{item.role} · {item.area}</p></div><Users size={17} className="text-blue-600" /></div><p className="mt-3 text-[11px] text-slate-500">Capacity: {item.capacity || "Not set"} · Backup: {item.backup || "Not assigned"}</p><div className="mt-3"><Button variant="danger" icon={Trash2} onClick={() => remove("owners", item.id)}>Remove</Button></div></div>)}</div>}</Section>}
    {modal === "queue" && <Modal title="Create assignment queue" onClose={() => setModal("")}><form onSubmit={addQueue} className="space-y-4"><Field label="Queue title" value={queueForm.title} onChange={(value) => setQueueForm({ ...queueForm, title: value })} placeholder="Monday triage review" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Queue type" options={QUEUES} value={queueForm.queue} onChange={(value) => setQueueForm({ ...queueForm, queue: value })} /><Field label="Owner" value={queueForm.owner} onChange={(value) => setQueueForm({ ...queueForm, owner: value })} /><Field label="Target" value={queueForm.target} onChange={(value) => setQueueForm({ ...queueForm, target: value })} placeholder="Review by 14:00" /></div><Area label="Summary" value={queueForm.summary} onChange={(value) => setQueueForm({ ...queueForm, summary: value })} placeholder="What is in this queue and what outcome is expected?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Create queue</Button></div></form></Modal>}
    {modal === "assignment" && <Modal title="Add assignment item" onClose={() => setModal("")}><form onSubmit={addAssignment} className="space-y-4"><Field label="Assignment title" value={assignmentForm.title} onChange={(value) => setAssignmentForm({ ...assignmentForm, title: value })} placeholder="Assign high-impact checkout report" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="State" options={STATES} value={assignmentForm.state} onChange={(value) => setAssignmentForm({ ...assignmentForm, state: value })} /><Field label="Priority" options={PRIORITIES} value={assignmentForm.priority} onChange={(value) => setAssignmentForm({ ...assignmentForm, priority: value })} /><Field label="Owner" value={assignmentForm.owner} onChange={(value) => setAssignmentForm({ ...assignmentForm, owner: value })} /><Field label="Due" value={assignmentForm.due} onChange={(value) => setAssignmentForm({ ...assignmentForm, due: value })} placeholder="Today" /></div><Area label="Detail" value={assignmentForm.detail} onChange={(value) => setAssignmentForm({ ...assignmentForm, detail: value })} placeholder="What must the assignee do next?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add assignment</Button></div></form></Modal>}
    {modal === "review" && <Modal title="Add queue review" onClose={() => setModal("")}><form onSubmit={addReview} className="space-y-4"><Field label="Review title" value={reviewForm.title} onChange={(value) => setReviewForm({ ...reviewForm, title: value })} placeholder="Review overdue critical reports" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Review type" options={REVIEW_TYPES} value={reviewForm.type} onChange={(value) => setReviewForm({ ...reviewForm, type: value })} /><Field label="State" options={["planned", "in-progress", "complete", "deferred"]} value={reviewForm.state} onChange={(value) => setReviewForm({ ...reviewForm, state: value })} /><Field label="Owner" value={reviewForm.owner} onChange={(value) => setReviewForm({ ...reviewForm, owner: value })} /><Field label="Next" value={reviewForm.next} onChange={(value) => setReviewForm({ ...reviewForm, next: value })} placeholder="Escalate to release lead" /></div><Area label="Finding" value={reviewForm.finding} onChange={(value) => setReviewForm({ ...reviewForm, finding: value })} placeholder="What did the review find?" /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add review</Button></div></form></Modal>}
    {modal === "note" && <Modal title="Add assignment note" onClose={() => setModal("")}><form onSubmit={addNote} className="space-y-4"><Field label="Note title" value={noteForm.title} onChange={(value) => setNoteForm({ ...noteForm, title: value })} placeholder="Routing rationale" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Kind" options={["Assignment note", "Handoff note", "Escalation note", "SLA note", "Resolution note", "Audit note"]} value={noteForm.kind} onChange={(value) => setNoteForm({ ...noteForm, kind: value })} /><Field label="Author" value={noteForm.author} onChange={(value) => setNoteForm({ ...noteForm, author: value })} /></div><Area label="Detail" value={noteForm.detail} onChange={(value) => setNoteForm({ ...noteForm, detail: value })} placeholder="Explain the assignment decision." /><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add note</Button></div></form></Modal>}
    {modal === "owner" && <Modal title="Add queue owner" onClose={() => setModal("")}><form onSubmit={addOwner} className="space-y-4"><Field label="Name" value={ownerForm.name} onChange={(value) => setOwnerForm({ ...ownerForm, name: value })} placeholder="Owner name" required /><div className="grid gap-4 sm:grid-cols-2"><Field label="Role" value={ownerForm.role} onChange={(value) => setOwnerForm({ ...ownerForm, role: value })} placeholder="Triage lead" /><Field label="Area" value={ownerForm.area} onChange={(value) => setOwnerForm({ ...ownerForm, area: value })} placeholder="Functional" /><Field label="Capacity" value={ownerForm.capacity} onChange={(value) => setOwnerForm({ ...ownerForm, capacity: value })} placeholder="3 active items" /><Field label="Backup" value={ownerForm.backup} onChange={(value) => setOwnerForm({ ...ownerForm, backup: value })} placeholder="Backup owner" /></div><div className="flex justify-end gap-2"><Button onClick={() => setModal("")}>Cancel</Button><Button type="submit" variant="primary">Add owner</Button></div></form></Modal>}
  </div></main>;
}
